package local

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"go.flipt.io/flipt/internal/storage"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

func Test_Store_String(t *testing.T) {
	assert.Equal(t, "local", (&SnapshotStore{}).String())
}

func Test_Store_CloseWithoutPolling(t *testing.T) {
	assert.NoError(t, (&SnapshotStore{}).Close())
}

func Test_Store(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)

	var closed bool
	ch := make(chan struct{})

	s, err := NewSnapshotStore(ctx, zap.NewNop(), "testdata", WithPollOptions(
		storagefs.WithInterval(1*time.Second),
		storagefs.WithNotify(t, func(modified bool) {
			if modified && !closed {
				closed = true
				close(ch)
			}
		}),
	))
	assert.NoError(t, err)

	dir, err := os.Getwd()
	assert.NoError(t, err)

	ftc := filepath.Join(dir, "testdata", "a.features.yml")

	defer func() {
		_, err := os.Stat(ftc)
		if err == nil {
			err := os.Remove(ftc)
			assert.NoError(t, err)
		}
	}()
	defer func() { assert.NoError(t, s.Close()) }()

	// change the filesystem contents
	assert.NoError(t, os.WriteFile(ftc, []byte(`{"namespace":"staging"}`), os.ModePerm))

	select {
	case <-ch:
	case <-time.After(10 * time.Second):
		t.Fatal("event not caught")
	}

	assert.NoError(t, s.View(func(s storage.ReadOnlyStore) error {
		_, err = s.GetNamespace(ctx, "staging")
		return err
	}))
}

package fs

import (
	"context"
	"io"
	"sync"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/containers"
	"go.uber.org/zap"
)

// UpdateFunc checks for changes to a snapshot.
type UpdateFunc func(context.Context) (bool, error)

type Poller struct {
	logger *zap.Logger
	ctx    context.Context
	cancel context.CancelFunc
	update UpdateFunc

	interval time.Duration
	notify   func(modified bool)

	mu     sync.Mutex
	closed bool
	active sync.WaitGroup
}

var _ io.Closer = (*Poller)(nil)

func WithInterval(interval time.Duration) containers.Option[Poller] {
	return func(p *Poller) {
		p.interval = interval
	}
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
	t.Helper()
	return func(p *Poller) {
		p.notify = n
	}
}

func NewPoller(ctx context.Context, logger *zap.Logger, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	ctx, cancel := context.WithCancel(ctx)
	p := &Poller{
		logger:   logger,
		ctx:      ctx,
		cancel:   cancel,
		update:   update,
		interval: 30 * time.Second,
	}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll is a utility function for a common polling strategy used by lots of declarative
// store implementations.
func (p *Poller) Poll() {
	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return
	}
	p.active.Add(1)
	p.mu.Unlock()
	defer p.active.Done()

	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			// A tick can be ready at the same time as cancellation.
			if p.ctx.Err() != nil {
				return
			}
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

// Close stops polling and waits for any active Poll calls to return.
func (p *Poller) Close() error {
	p.mu.Lock()
	p.closed = true
	p.cancel()
	p.mu.Unlock()
	p.active.Wait()
	return nil
}

